-- Additive V2 templates. IDs for MESS templates match unified-7day-planner.ts.
-- Food references resolve by canonical name to the existing live foods.id.
BEGIN;
LOCK TABLE public.meal_templates, public.meal_template_slots, public.meal_template_slot_options IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM (VALUES
    ('PG_MESS_BREAKFAST', '47d4ad56-5e4a-4872-8bfe-bb732bde43a8'),
    ('PG_MESS_LUNCH', '06ccef21-dc61-4c7c-9595-b43f3ff0149e'),
    ('PG_MESS_DINNER', '800f6120-0137-48ef-960e-f389c651ad06'),
    ('HOSTEL_MESS_BREAKFAST', '4e898ec2-5ed7-45a8-b24a-d06342a5ffc8'),
    ('HOSTEL_MESS_LUNCH', '62a35dc1-7bb6-437d-abec-64cb201a153b'),
    ('HOSTEL_MESS_DINNER', 'a2d0e402-4ab9-4a6d-a580-2867e88a99d5'),
    ('OFFICE_CANTEEN_MESS_BREAKFAST', 'fb74058a-6a90-4953-957a-a26e1408938d'),
    ('OFFICE_CANTEEN_MESS_LUNCH', 'c6f8b608-87a5-4748-b771-7d5bc6685853'),
    ('OFFICE_CANTEEN_MESS_DINNER', '90117884-480e-4eb4-938e-28ea11bb2b98'),
    ('HOSTEL_NO_MESS_BREAKFAST', 'facbf87c-1bd7-484d-8932-8e633d014b33'),
    ('HOSTEL_NO_MESS_LUNCH', '4f3ff3be-f075-442b-8941-c3f78c4c8875'),
    ('HOSTEL_NO_MESS_DINNER', 'a4b734b0-e190-4865-9043-b4767024c07b'),
    ('HOME_NO_MESS_BREAKFAST', '44957fe3-c0b9-4015-a6f9-e8632f1e2afe'),
    ('HOME_NO_MESS_LUNCH', 'bc6ad0da-42be-40b6-aa0d-2a04c6796fe7'),
    ('HOME_NO_MESS_DINNER', '82ce363a-8006-46f7-b7a1-d2f19ceb868d')
  ) AS seed(code, id) JOIN public.meal_templates t ON t.code = seed.code WHERE t.id <> seed.id::uuid) THEN
    RAISE EXCEPTION 'TEMPLATE_ID_CONFLICT: existing template code has a different ID';
  END IF;
  IF EXISTS (SELECT 1 FROM (VALUES
    ('Chapati / Phulka'),
    ('White Rice (Steamed)'),
    ('Yellow Moong Dal'),
    ('Dal Tadka'),
    ('Mixed Vegetable Sabzi'),
    ('Green Salad with Lemon'),
    ('Moong Sprouts Salad'),
    ('Roasted Chana (Dry Chickpeas)'),
    ('Low Fat Paneer'),
    ('Low Fat Curd / Dahi'),
    ('Boiled Egg (Whole)'),
    ('Boiled Egg White'),
    ('Whole Wheat Bread'),
    ('Banana'),
    ('Tofu (Firm)')
  ) AS seed(name) LEFT JOIN public.foods f ON f.name = seed.name WHERE f.id IS NULL) THEN
    RAISE EXCEPTION 'TEMPLATE_FOOD_MISSING: a required food name is absent';
  END IF;
END $$;
